64	/// Layout the scaled content.
65	#[typst_macros::time(span = elem.span())]
66	pub fn layout_scale(
67	    elem: &Packed<ScaleElem>,
68	    engine: &mut Engine,
69	    locator: Locator,
70	    styles: StyleChain,
71	    region: Region,
72	) -> SourceResult<Frame> {
73	    // Compute the new region's approximate size.
74	    let scale = resolve_scale(elem, engine, locator.relayout(), region.size, styles)?;
75	    let size = region
76	        .size
77	        .zip_map(scale, |r, s| if r.is_finite() { Ratio::new(1.0 / s).of(r) } else { r })
78	        .map(Abs::abs);
79	
80	    measure_and_layout(
81	        engine,
82	        locator,
83	        region,
84	        size,
85	        styles,
86	        &elem.body,
87	        Transform::scale(scale.x, scale.y),
88	        elem.origin.resolve(styles),
89	        elem.reflow.get(styles),
90	        // TODO: Figure out where the baseline should go after a vertical flip.
91	        // Similar problem to >90deg rotation, as following the baseline would
92	        // lead text to go below the typical baseline. For now, simply do not
93	        // preserve the baseline if vertical scale is negative.
94	        scale.y.get() >= 0.0,
95	    )
96	}
