98	/// Resolves scale parameters, preserving aspect ratio if one of the scales
99	/// is set to `auto`.
100	fn resolve_scale(
101	    elem: &Packed<ScaleElem>,
102	    engine: &mut Engine,
103	    locator: Locator,
104	    container: Size,
105	    styles: StyleChain,
106	) -> SourceResult<Axes<Ratio>> {
107	    fn resolve_axis(
108	        axis: Smart<ScaleAmount>,
109	        body: impl Fn() -> SourceResult<Abs>,
110	        styles: StyleChain,
111	    ) -> SourceResult<Smart<Ratio>> {
112	        Ok(match axis {
113	            Smart::Auto => Smart::Auto,
114	            Smart::Custom(amt) => Smart::Custom(match amt {
115	                ScaleAmount::Ratio(ratio) => ratio,
116	                ScaleAmount::Length(length) => {
117	                    let length = length.resolve(styles);
118	                    Ratio::new(length / body()?)
119	                }
120	            }),
121	        })
122	    }
123	
124	    let size = LazyCell::new(|| {
125	        let pod = Region::new(container, Axes::splat(false));
126	        let frame = crate::layout_frame(engine, &elem.body, locator, styles, pod)?;
127	        SourceResult::Ok(frame.size())
128	    });
129	
130	    let x = resolve_axis(
131	        elem.x.get(styles),
132	        || size.as_ref().map(|size| size.x).map_err(Clone::clone),
133	        styles,
134	    )?;
135	
136	    let y = resolve_axis(
137	        elem.y.get(styles),
138	        || size.as_ref().map(|size| size.y).map_err(Clone::clone),
139	        styles,
140	    )?;
141	
142	    match (x, y) {
143	        (Smart::Auto, Smart::Auto) => {
144	            bail!(elem.span(), "x and y cannot both be auto")
145	        }
146	        (Smart::Custom(x), Smart::Custom(y)) => Ok(Axes::new(x, y)),
147	        (Smart::Auto, Smart::Custom(v)) | (Smart::Custom(v), Smart::Auto) => {
148	            Ok(Axes::splat(v))
149	        }
150	    }
151	}
152	
153	/// Layout the skewed content.
154	#[typst_macros::time(span = elem.span())]
155	pub fn layout_skew(
156	    elem: &Packed<SkewElem>,
157	    engine: &mut Engine,
158	    locator: Locator,
159	    styles: StyleChain,
160	    region: Region,
161	) -> SourceResult<Frame> {
162	    let ax = elem.ax.get(styles);
163	    let ay = elem.ay.get(styles);
164	    let align = elem.origin.resolve(styles);
165	
166	    // Compute the new region's approximate size.
167	    let size = if region.size.is_finite() {
168	        compute_bounding_box(region.size, Transform::skew(ax, ay)).1
169	    } else {
170	        Size::splat(Abs::inf())
171	    };
172	
173	    measure_and_layout(
174	        engine,
175	        locator,
176	        region,
177	        size,
178	        styles,
179	        &elem.body,
180	        Transform::skew(ax, ay),
181	        align,
182	        elem.reflow.get(styles),
183	        true,
184	    )
185	}
186	
187	/// Applies a transformation to a frame, reflowing the layout if necessary.
188	#[expect(clippy::too_many_arguments)]
189	fn measure_and_layout(
190	    engine: &mut Engine,
191	    locator: Locator,
192	    region: Region,
193	    size: Size,
194	    styles: StyleChain,
195	    body: &Content,
196	    transform: Transform,
197	    align: Axes<FixedAlignment>,
198	    reflow: bool,
199	    keep_baseline: bool,
200	) -> SourceResult<Frame> {
201	    if reflow {
202	        // Measure the size of the body.
203	        let pod = Region::new(size, Axes::splat(false));
204	        let frame = crate::layout_frame(engine, body, locator.relayout(), styles, pod)?;
205	
206	        // Actually perform the layout.
207	        let pod = Region::new(frame.size(), Axes::splat(true));
208	        let mut frame = crate::layout_frame(engine, body, locator, styles, pod)?;
209	        let Axes { x, y } = align.zip_map(frame.size(), FixedAlignment::position);
210	
211	        // Compute the transform.
212	        let ts = Transform::translate(x, y)
213	            .pre_concat(transform)
214	            .pre_concat(Transform::translate(-x, -y));
215	
216	        // Compute a new baseline that goes through the transformed baseline
217	        // (when seen as a hypothetical line crossing the frame at the baseline
218	        // height). To do this, we use the height of one point at baseline
219	        // height after it undergoes transformation - in this case, the middle
220	        // point.
221	        //
222	        // Note that, when only scaling, the chosen point doesn't matter as the
223	        // height of all transformed points at baseline height will be the same,
224	        // but, when skewing, this would ensure the new baseline will cross the
225	        // middle of the old baseline.
226	        //
227	        // For now, however, rotation with reflow, in particular, does not yet
228	        // preserve baselines as it's not yet clear that such a baseline change
229	        // would be an expected outcome of rotation. (For example, a 180-degree
230	        // rotation would cause the baseline to be above the text!)
231	        let new_baseline = (frame.has_baseline() && keep_baseline)
232	            .then(|| Point::new(frame.width() / 2.0, frame.baseline()).transform(ts).y);
233	
234	        // Compute the bounding box and offset and wrap in a new frame.
235	        let (offset, size) = compute_bounding_box(frame.size(), ts);
236	        frame.transform(ts);
237	        frame.translate_visual(offset);
238	        frame.set_size(size);
239	
240	        if let Some(new_baseline) = new_baseline {
241	            frame.set_baseline(new_baseline + offset.y);
242	        } else if !keep_baseline {
243	            // Post-transformation baseline is not clear.
244	            frame.clear_baseline();
245	        }
246	
247	        Ok(frame)
248	    } else {
249	        // Layout the body.
250	        let mut frame = crate::layout_frame(engine, body, locator, styles, region)?;
251	        let Axes { x, y } = align.zip_map(frame.size(), FixedAlignment::position);
252	
253	        // Compute the transform.
254	        let ts = Transform::translate(x, y)
255	            .pre_concat(transform)
256	            .pre_concat(Transform::translate(-x, -y));
257	
258	        // Apply the transform.
259	        frame.transform(ts);
260	        Ok(frame)
261	    }
262	}
263	
264	/// Computes the bounding box and offset of a transformed area.
265	fn compute_bounding_box(size: Size, ts: Transform) -> (Point, Size) {
266	    let top_left = Point::zero().transform_inf(ts);
267	    let top_right = Point::with_x(size.x).transform_inf(ts);
268	    let bottom_left = Point::with_y(size.y).transform_inf(ts);
269	    let bottom_right = size.to_point().transform_inf(ts);
270	
271	    // We first compute the new bounding box of the rotated area.
272	    let min_x = top_left.x.min(top_right.x).min(bottom_left.x).min(bottom_right.x);
273	    let min_y = top_left.y.min(top_right.y).min(bottom_left.y).min(bottom_right.y);
274	    let max_x = top_left.x.max(top_right.x).max(bottom_left.x).max(bottom_right.x);
275	    let max_y = top_left.y.max(top_right.y).max(bottom_left.y).max(bottom_right.y);
276	
277	    // Then we compute the new size of the area.
278	    let width = max_x - min_x;
279	    let height = max_y - min_y;
280	
281	    (Point::new(-min_x, -min_y), Size::new(width.abs(), height.abs()))
282	}
