1	use typst_library::foundations::StyleChain;
2	use typst_library::layout::{Abs, Fragment, Frame, FrameItem, HideElem, Point, Sides};
3	use typst_library::model::{Destination, LinkElem, ParElem};
4	
5	/// Frame-level modifications resulting from styles that do not impose any
6	/// layout structure.
7	///
8	/// These are always applied at the highest level of style uniformity.
9	/// Consequently, they must be applied by all layouters that manually manage
10	/// styles of their children (because they can produce children with varying
11	/// styles). This currently includes flow, inline, and math layout.
12	///
13	/// Other layouters don't manually need to handle it because their parents that
14	/// result from realization will take care of it and the styles can only apply
15	/// to them as a whole, not part of it (since they don't manage styles).
16	///
17	/// Currently existing frame modifiers are:
18	/// - `HideElem::hidden`
19	/// - `LinkElem::dests`
20	#[derive(Debug, Clone)]
21	pub struct FrameModifiers {
22	    /// A destination to link to.
23	    dest: Option<Destination>,
24	    /// Whether the contents of the frame should be hidden.
25	    hidden: bool,
26	}
27	
28	impl FrameModifiers {
29	    /// Retrieve all modifications that should be applied per-frame.
30	    pub fn get_in(styles: StyleChain) -> Self {
31	        Self {
32	            dest: styles.get_cloned(LinkElem::current),
33	            hidden: styles.get(HideElem::hidden),
34	        }
35	    }
36	}
37	
38	/// Applies [`FrameModifiers`].
39	pub trait FrameModify {
40	    /// Apply the modifiers in-place.
41	    fn modify(&mut self, modifiers: &FrameModifiers);
42	
43	    /// Apply the modifiers, and return the modified result.
44	    fn modified(mut self, modifiers: &FrameModifiers) -> Self
45	    where
46	        Self: Sized,
47	    {
48	        self.modify(modifiers);
49	        self
50	    }
51	}
52	
53	impl FrameModify for Frame {
54	    fn modify(&mut self, modifiers: &FrameModifiers) {
55	        modify_frame(self, modifiers, None);
56	    }
57	}
58	
59	impl FrameModify for Fragment {
60	    fn modify(&mut self, modifiers: &FrameModifiers) {
61	        for frame in self.iter_mut() {
62	            frame.modify(modifiers);
63	        }
64	    }
65	}
66	
67	impl<T, E> FrameModify for Result<T, E>
68	where
69	    T: FrameModify,
70	{
71	    fn modify(&mut self, props: &FrameModifiers) {
72	        if let Ok(inner) = self {
73	            inner.modify(props);
74	        }
75	    }
76	}
77	
78	pub trait FrameModifyText {
79	    /// Resolve and apply [`FrameModifiers`] for this text frame.
80	    fn modify_text(&mut self, styles: StyleChain);
81	}
82	
83	impl FrameModifyText for Frame {
84	    fn modify_text(&mut self, styles: StyleChain) {
85	        let modifiers = FrameModifiers::get_in(styles);
86	        let expand_y = 0.5 * styles.resolve(ParElem::leading);
87	        let outset = Sides::new(Abs::zero(), expand_y, Abs::zero(), expand_y);
88	        modify_frame(self, &modifiers, Some(outset));
89	    }
90	}
91	
92	fn modify_frame(
93	    frame: &mut Frame,
94	    modifiers: &FrameModifiers,
95	    link_box_outset: Option<Sides<Abs>>,
96	) {
97	    if let Some(dest) = &modifiers.dest {
98	        let mut pos = Point::zero();
99	        let mut size = frame.size();
100	        if let Some(outset) = link_box_outset {
101	            pos.y -= outset.top;
102	            pos.x -= outset.left;
103	            size += outset.sum_by_axis();
104	        }
105	        frame.push(pos, FrameItem::Link(dest.clone(), size));
106	    }
107	
108	    if modifiers.hidden {
109	        frame.hide();
110	    }
111	}
