19	/// Layout the line.
20	#[typst_macros::time(span = elem.span())]
21	pub fn layout_line(
22	    elem: &Packed<LineElem>,
23	    _: &mut Engine,
24	    _: Locator,
25	    styles: StyleChain,
26	    region: Region,
27	) -> SourceResult<Frame> {
28	    let resolve = |axes: Axes<Rel<Abs>>| axes.zip_map(region.size, Rel::relative_to);
29	    let start = resolve(elem.start.resolve(styles));
30	    let delta = elem
31	        .end
32	        .resolve(styles)
33	        .map(|end| resolve(end) - start)
34	        .unwrap_or_else(|| {
35	            let length = elem.length.resolve(styles);
36	            let angle = elem.angle.get(styles);
37	            let x = angle.cos() * length;
38	            let y = angle.sin() * length;
39	            resolve(Axes::new(x, y))
40	        });
41	
42	    let stroke = elem.stroke.resolve(styles).unwrap_or_default();
43	    let size = start.max(start + delta).max(Size::zero());
44	
45	    if !size.is_finite() {
46	        bail!(elem.span(), "cannot create line with infinite length");
47	    }
48	
49	    let mut frame = Frame::soft(size);
50	    let shape = Geometry::Line(delta.to_point()).stroked(stroke);
51	    frame.push(start.to_point(), FrameItem::Shape(shape, elem.span()));
52	    Ok(frame)
53	}
