55	/// Layout the curve.
56	#[typst_macros::time(span = elem.span())]
57	pub fn layout_curve(
58	    elem: &Packed<CurveElem>,
59	    _: &mut Engine,
60	    _: Locator,
61	    styles: StyleChain,
62	    region: Region,
63	) -> SourceResult<Frame> {
64	    let mut builder = CurveBuilder::new(region, styles);
65	
66	    for item in &elem.components {
67	        match item {
68	            CurveComponent::Move(element) => {
69	                let relative = element.relative.get(styles);
70	                let point = builder.resolve_point(element.start, relative);
71	                builder.move_(point);
72	            }
73	
74	            CurveComponent::Line(element) => {
75	                let relative = element.relative.get(styles);
76	                let point = builder.resolve_point(element.end, relative);
77	                builder.line(point);
78	            }
79	
80	            CurveComponent::Quad(element) => {
81	                let relative = element.relative.get(styles);
82	                let end = builder.resolve_point(element.end, relative);
83	                let control = match element.control {
84	                    Smart::Auto => {
85	                        control_c2q(builder.last_point, builder.last_control_from)
86	                    }
87	                    Smart::Custom(Some(p)) => builder.resolve_point(p, relative),
88	                    Smart::Custom(None) => end,
89	                };
90	                builder.quad(control, end);
91	            }
92	
93	            CurveComponent::Cubic(element) => {
94	                let relative = element.relative.get(styles);
95	                let end = builder.resolve_point(element.end, relative);
96	                let c1 = match element.control_start {
97	                    Some(Smart::Custom(p)) => builder.resolve_point(p, relative),
98	                    Some(Smart::Auto) => builder.last_control_from,
99	                    None => builder.last_point,
100	                };
101	                let c2 = match element.control_end {
102	                    Some(p) => builder.resolve_point(p, relative),
103	                    None => end,
104	                };
105	                builder.cubic(c1, c2, end);
106	            }
107	
108	            CurveComponent::Close(element) => {
109	                builder.close(element.mode.get(styles));
110	            }
111	        }
112	    }
113	
114	    let (curve, size) = builder.finish();
115	    if curve.is_empty() {
116	        return Ok(Frame::soft(size));
117	    }
118	
119	    if !size.is_finite() {
120	        bail!(elem.span(), "cannot create curve with infinite size");
121	    }
122	
123	    // Prepare fill and stroke.
124	    let fill = elem.fill.get_cloned(styles);
125	    let fill_rule = elem.fill_rule.get(styles);
126	    let stroke = match elem.stroke.resolve(styles) {
127	        Smart::Auto if fill.is_none() => Some(FixedStroke::default()),
128	        Smart::Auto => None,
129	        Smart::Custom(stroke) => stroke.map(Stroke::unwrap_or_default),
130	    };
131	
132	    let mut frame = Frame::soft(size);
133	    let shape = Shape {
134	        geometry: Geometry::Curve(curve),
135	        stroke,
136	        fill,
137	        fill_rule,
138	    };
139	    frame.push(Point::zero(), FrameItem::Shape(shape, elem.span()));
140	    Ok(frame)
141	}
