143	/// Builds a `Curve` from a [`CurveElem`]'s parts.
144	struct CurveBuilder<'a> {
145	    /// The output curve.
146	    curve: Curve,
147	    /// The curve's bounds.
148	    size: Size,
149	    /// The region relative to which points are resolved.
150	    region: Region,
151	    /// The styles for the curve.
152	    styles: StyleChain<'a>,
153	    /// The next start point.
154	    start_point: Point,
155	    /// Mirror of the first cubic start control point (for closing).
156	    start_control_into: Point,
157	    /// The point we previously ended on.
158	    last_point: Point,
159	    /// Mirror of the last cubic control point (for auto control points).
160	    last_control_from: Point,
161	    /// Whether a component has been start. This does not mean that something
162	    /// has been added to `self.curve` yet.
163	    is_started: bool,
164	    /// Whether anything was added to `self.curve` for the current component.
165	    is_empty: bool,
166	}
167	
168	impl<'a> CurveBuilder<'a> {
169	    /// Create a new curve builder.
170	    fn new(region: Region, styles: StyleChain<'a>) -> Self {
171	        Self {
172	            curve: Curve::new(),
173	            size: Size::zero(),
174	            region,
175	            styles,
176	            start_point: Point::zero(),
177	            start_control_into: Point::zero(),
178	            last_point: Point::zero(),
179	            last_control_from: Point::zero(),
180	            is_started: false,
181	            is_empty: true,
182	        }
183	    }
184	
185	    /// Finish building, returning the curve and its bounding size.
186	    fn finish(self) -> (Curve, Size) {
187	        (self.curve, self.size)
188	    }
189	
190	    /// Move to a point, starting a new segment.
191	    fn move_(&mut self, point: Point) {
192	        // Delay calling `curve.move` in case there is another move element
193	        // before any actual drawing.
194	        self.expand_bounds(point);
195	        self.start_point = point;
196	        self.start_control_into = point;
197	        self.last_point = point;
198	        self.last_control_from = point;
199	        self.is_started = true;
200	        self.is_empty = true;
201	    }
202	
203	    /// Add a line segment.
204	    fn line(&mut self, point: Point) {
205	        if self.is_empty {
206	            self.start_component();
207	            self.start_control_into = self.start_point;
208	        }
209	        self.curve.line(point);
210	        self.expand_bounds(point);
211	        self.last_point = point;
212	        self.last_control_from = point;
213	    }
214	
215	    /// Add a quadratic curve segment.
216	    fn quad(&mut self, control: Point, end: Point) {
217	        let c1 = control_q2c(self.last_point, control);
218	        let c2 = control_q2c(end, control);
219	        self.cubic(c1, c2, end);
220	    }
221	
222	    /// Add a cubic curve segment.
223	    fn cubic(&mut self, c1: Point, c2: Point, end: Point) {
224	        if self.is_empty {
225	            self.start_component();
226	            self.start_control_into = mirror_c(self.start_point, c1);
227	        }
228	        self.curve.cubic(c1, c2, end);
229	
230	        let p0 = point_to_kurbo(self.last_point);
231	        let p1 = point_to_kurbo(c1);
232	        let p2 = point_to_kurbo(c2);
233	        let p3 = point_to_kurbo(end);
234	        let extrema = CubicBez::new(p0, p1, p2, p3).bounding_box();
235	        self.size.x.set_max(Abs::raw(extrema.x1));
236	        self.size.y.set_max(Abs::raw(extrema.y1));
237	
238	        self.last_point = end;
239	        self.last_control_from = mirror_c(end, c2);
240	    }
241	
242	    /// Close the curve if it was opened.
243	    fn close(&mut self, mode: CloseMode) {
244	        if self.is_started && !self.is_empty {
245	            if mode == CloseMode::Smooth {
246	                self.cubic(
247	                    self.last_control_from,
248	                    self.start_control_into,
249	                    self.start_point,
250	                );
251	            }
252	            self.curve.close();
253	            self.last_point = self.start_point;
254	            self.last_control_from = self.start_point;
255	        }
256	        self.is_started = false;
257	        self.is_empty = true;
258	    }
259	
260	    /// Push the initial move component.
261	    fn start_component(&mut self) {
262	        self.curve.move_(self.start_point);
263	        self.is_empty = false;
264	        self.is_started = true;
265	    }
266	
267	    /// Expand the curve's bounding box.
268	    fn expand_bounds(&mut self, point: Point) {
269	        self.size.x.set_max(point.x);
270	        self.size.y.set_max(point.y);
271	    }
272	
273	    /// Resolve the point relative to the region.
274	    fn resolve_point(&self, point: Axes<Rel>, relative: bool) -> Point {
275	        let mut p = point
276	            .resolve(self.styles)
277	            .zip_map(self.region.size, Rel::relative_to)
278	            .to_point();
279	        if relative {
280	            p += self.last_point;
281	        }
282	        p
283	    }
284	}
285	
286	/// Convert a cubic control point into a quadratic one.
287	fn control_c2q(p: Point, c: Point) -> Point {
288	    1.5 * c - 0.5 * p
289	}
290	
291	/// Convert a quadratic control point into a cubic one.
292	fn control_q2c(p: Point, c: Point) -> Point {
293	    (p + 2.0 * c) / 3.0
294	}
295	
296	/// Mirror a control point.
297	fn mirror_c(p: Point, c: Point) -> Point {
298	    2.0 * p - c
299	}
300	
301	/// Convert a point to a `kurbo::Point`.
302	fn point_to_kurbo(point: Point) -> kurbo::Point {
303	    kurbo::Point::new(point.x.to_raw(), point.y.to_raw())
304	}
