306	/// Layout the polygon.
307	#[typst_macros::time(span = elem.span())]
308	pub fn layout_polygon(
309	    elem: &Packed<PolygonElem>,
310	    _: &mut Engine,
311	    _: Locator,
312	    styles: StyleChain,
313	    region: Region,
314	) -> SourceResult<Frame> {
315	    let points: Vec<Point> = elem
316	        .vertices
317	        .iter()
318	        .map(|c| c.resolve(styles).zip_map(region.size, Rel::relative_to).to_point())
319	        .collect();
320	
321	    let size = points.iter().fold(Point::zero(), |max, c| c.max(max)).to_size();
322	    if !size.is_finite() {
323	        bail!(elem.span(), "cannot create polygon with infinite size");
324	    }
325	
326	    let mut frame = Frame::soft(size);
327	
328	    // Only create a curve if there are more than zero points.
329	    if points.is_empty() {
330	        return Ok(frame);
331	    }
332	
333	    // Prepare fill and stroke.
334	    let fill = elem.fill.get_cloned(styles);
335	    let fill_rule = elem.fill_rule.get(styles);
336	    let stroke = match elem.stroke.resolve(styles) {
337	        Smart::Auto if fill.is_none() => Some(FixedStroke::default()),
338	        Smart::Auto => None,
339	        Smart::Custom(stroke) => stroke.map(Stroke::unwrap_or_default),
340	    };
341	
342	    // Construct a closed curve given all points.
343	    let mut curve = Curve::new();
344	    curve.move_(points[0]);
345	    for &point in &points[1..] {
346	        curve.line(point);
347	    }
348	    curve.close();
349	
350	    let shape = Shape {
351	        geometry: Geometry::Curve(curve),
352	        stroke,
353	        fill,
354	        fill_rule,
355	    };
356	    frame.push(Point::zero(), FrameItem::Shape(shape, elem.span()));
357	    Ok(frame)
358	}
