460	/// A category of shape.
461	#[derive(Debug, Copy, Clone, Eq, PartialEq, Hash)]
462	enum ShapeKind {
463	    /// A rectangle with equal side lengths.
464	    Square,
465	    /// A quadrilateral with four right angles.
466	    Rect,
467	    /// An ellipse with coinciding foci.
468	    Circle,
469	    /// A curve around two focal points.
470	    Ellipse,
471	}
472	
473	impl ShapeKind {
474	    /// Whether this shape kind is curvy.
475	    fn is_round(self) -> bool {
476	        matches!(self, Self::Circle | Self::Ellipse)
477	    }
478	
479	    /// Whether this shape kind has equal side length.
480	    fn is_quadratic(self) -> bool {
481	        matches!(self, Self::Square | Self::Circle)
482	    }
483	}
