485	/// Layout a shape.
486	#[expect(clippy::too_many_arguments)]
487	fn layout_shape(
488	    engine: &mut Engine,
489	    locator: Locator,
490	    styles: StyleChain,
491	    region: Region,
492	    kind: ShapeKind,
493	    body: &Option<Content>,
494	    fill: Option<Paint>,
495	    stroke: Smart<Sides<Option<Option<Stroke<Abs>>>>>,
496	    inset: Sides<Option<Rel<Abs>>>,
497	    outset: Sides<Option<Rel<Abs>>>,
498	    radius: Corners<Option<Rel<Abs>>>,
499	    span: Span,
500	) -> SourceResult<Frame> {
501	    let mut frame;
502	    if let Some(child) = body {
503	        let mut inset = inset.unwrap_or_default();
504	        if kind.is_round() {
505	            // Apply extra inset to round shapes.
506	            inset = inset.map(|v| v + Ratio::new(0.5 - SQRT_2 / 4.0));
507	        }
508	        let has_inset = !inset.is_zero();
509	
510	        // Take the inset, if any, into account.
511	        let mut pod = region;
512	        if has_inset {
513	            pod.size = crate::pad::shrink(region.size, &inset);
514	        }
515	
516	        // If the shape is quadratic, we first measure it to determine its size
517	        // and then layout with full expansion to force the aspect ratio and
518	        // make sure it's really quadratic.
519	        if kind.is_quadratic() {
520	            let length = match quadratic_size(pod) {
521	                Some(length) => length,
522	                None => {
523	                    // Take as much as the child wants, but without overflowing.
524	                    crate::layout_frame(engine, child, locator.relayout(), styles, pod)?
525	                        .size()
526	                        .max_by_side()
527	                        .min(pod.size.min_by_side())
528	                }
529	            };
530	
531	            pod = Region::new(Size::splat(length), Axes::splat(true));
532	        }
533	
534	        // Layout the child.
535	        frame = crate::layout_frame(engine, child, locator, styles, pod)?;
536	
537	        // Apply the inset.
538	        if has_inset {
539	            crate::pad::grow(&mut frame, &inset);
540	        }
541	    } else {
542	        // The default size that a shape takes on if it has no child and no
543	        // forced sizes.
544	        let default = Size::new(Abs::pt(45.0), Abs::pt(30.0)).min(region.size);
545	
546	        let size = if kind.is_quadratic() {
547	            Size::splat(match quadratic_size(region) {
548	                Some(length) => length,
549	                None => default.min_by_side(),
550	            })
551	        } else {
552	            // For each dimension, pick the region size if forced, otherwise
553	            // use the default size (or the region size if the default
554	            // is too large for the region).
555	            region.expand.select(region.size, default)
556	        };
557	
558	        frame = Frame::soft(size);
559	    }
560	
561	    // Prepare stroke.
562	    let stroke = match stroke {
563	        Smart::Auto if fill.is_none() => Sides::splat(Some(FixedStroke::default())),
564	        Smart::Auto => Sides::splat(None),
565	        Smart::Custom(strokes) => {
566	            strokes.unwrap_or_default().map(|s| s.map(Stroke::unwrap_or_default))
567	        }
568	    };
569	
570	    // Add fill and/or stroke.
571	    if fill.is_some() || stroke.iter().any(Option::is_some) {
572	        if kind.is_round() {
573	            let outset = outset.unwrap_or_default().relative_to(frame.size());
574	            let size = frame.size() + outset.sum_by_axis();
575	            let pos = Point::new(-outset.left, -outset.top);
576	            let shape = Shape {
577	                geometry: Geometry::Curve(Curve::ellipse(size)),
578	                fill,
579	                stroke: stroke.left,
580	                fill_rule: FillRule::default(),
581	            };
582	            frame.prepend(pos, FrameItem::Shape(shape, span));
583	        } else {
584	            fill_and_stroke(
585	                &mut frame,
586	                fill,
587	                &stroke,
588	                &outset.unwrap_or_default(),
589	                &radius.unwrap_or_default(),
590	                span,
591	            );
592	        }
593	    }
594	
595	    Ok(frame)
596	}
