598	/// Determines the forced size of a quadratic shape based on the region, if any.
599	///
600	/// The size is forced if at least one axis is expanded because `expand` is
601	/// `true` for axes whose size was manually specified by the user.
602	fn quadratic_size(region: Region) -> Option<Abs> {
603	    if region.expand.x && region.expand.y {
604	        // If both `width` and `height` are specified, we choose the
605	        // smaller one.
606	        Some(region.size.x.min(region.size.y))
607	    } else if region.expand.x {
608	        Some(region.size.x)
609	    } else if region.expand.y {
610	        Some(region.size.y)
611	    } else {
612	        None
613	    }
614	}
