616	/// Creates a new rectangle as a curve.
617	pub fn clip_rect(
618	    size: Size,
619	    radius: &Corners<Rel<Abs>>,
620	    stroke: &Sides<Option<FixedStroke>>,
621	    outset: &Sides<Rel<Abs>>,
622	) -> Curve {
623	    let outset = outset.relative_to(size);
624	    let size = size + outset.sum_by_axis();
625	
626	    let stroke_widths = stroke.as_ref().map(|s| s.as_ref().map(|s| s.thickness / 2.0));
627	
628	    let base_radius = size.x.min(size.y) / 2.0;
629	    let corner_max =
630	        stroke_widths.map_corners(|a, b| base_radius + a.min(b).unwrap_or(Abs::zero()));
631	
632	    let radius = radius
633	        .zip(corner_max)
634	        .map(|(value, max)| value.relative_to(max * 2.0).min(max));
635	    let corners = corners_control_points(size, &radius, stroke, &stroke_widths);
636	
637	    let mut curve = Curve::new();
638	    if corners.top_left.arc_inner() {
639	        curve.arc_move(
640	            corners.top_left.start_inner(),
641	            corners.top_left.center_inner(),
642	            corners.top_left.end_inner(),
643	        );
644	    } else {
645	        curve.move_(corners.top_left.center_inner());
646	    }
647	    for corner in [&corners.top_right, &corners.bottom_right, &corners.bottom_left] {
648	        if corner.arc_inner() {
649	            curve.arc_line(
650	                corner.start_inner(),
651	                corner.center_inner(),
652	                corner.end_inner(),
653	            );
654	        } else {
655	            curve.line(corner.center_inner());
656	        }
657	    }
658	    curve.close();
659	    curve.translate(Point::new(-outset.left, -outset.top));
660	    curve
661	}
