663	/// Add a fill and stroke with optional radius and outset to the frame.
664	pub fn fill_and_stroke(
665	    frame: &mut Frame,
666	    fill: Option<Paint>,
667	    stroke: &Sides<Option<FixedStroke>>,
668	    outset: &Sides<Rel<Abs>>,
669	    radius: &Corners<Rel<Abs>>,
670	    span: Span,
671	) {
672	    let outset = outset.relative_to(frame.size());
673	    let size = frame.size() + outset.sum_by_axis();
674	    let pos = Point::new(-outset.left, -outset.top);
675	    frame.prepend_multiple(
676	        styled_rect(size, radius, fill, stroke)
677	            .into_iter()
678	            .map(|x| (pos, FrameItem::Shape(x, span))),
679	    );
680	}
