712	
713	fn corners_control_points(
714	    size: Size,
715	    radius: &Corners<Abs>,
716	    strokes: &Sides<Option<FixedStroke>>,
717	    stroke_widths: &Sides<Option<Abs>>,
718	) -> Corners<ControlPoints> {
719	    Corners {
720	        top_left: Corner::TopLeft,
721	        top_right: Corner::TopRight,
722	        bottom_right: Corner::BottomRight,
723	        bottom_left: Corner::BottomLeft,
724	    }
725	    .map(|corner| ControlPoints {
726	        radius: radius.get(corner),
727	        stroke_before: stroke_widths.get(corner.side_ccw()),
728	        stroke_after: stroke_widths.get(corner.side_cw()),
729	        corner,
730	        size,
731	        same: match (
732	            strokes.get_ref(corner.side_ccw()),
733	            strokes.get_ref(corner.side_cw()),
734	        ) {
735	            (Some(a), Some(b)) => {
736	                // Solid strokes can be drawn as `fill_segment`s.
737	                let solid =
738	                    a.dash.as_ref().map(|dash| dash.array.is_empty()).unwrap_or(true);
739	
740	                // For solid strokes the caps are only relevant for the end of
741	                // the strokes, and they can be filled. For dashed strokes the
742	                // cap determines how the entire line is drawn, thus there
743	                // should be two different segments if the cap differs.
744	                let filled_segment_same = a.paint == b.paint && a.dash == b.dash;
745	                let stroke_segment_same = a.cap == b.cap && a.thickness == b.thickness;
746	
747	                filled_segment_same && (solid || stroke_segment_same)
748	            }
749	            (None, None) => true,
750	            _ => false,
751	        },
752	    })
753	}
754	
755	/// Use stroke and fill for the rectangle
756	fn segmented_rect(
757	    size: Size,
758	    radius: &Corners<Rel<Abs>>,
759	    fill: Option<Paint>,
760	    strokes: &Sides<Option<FixedStroke>>,
761	) -> Vec<Shape> {
762	    let mut res = vec![];
763	    let stroke_widths = strokes.as_ref().map(|s| s.as_ref().map(|s| s.thickness / 2.0));
764	
765	    let base_radius = size.x.abs().min(size.y.abs()) / 2.0;
766	    let corner_max =
767	        stroke_widths.map_corners(|a, b| base_radius + a.min(b).unwrap_or(Abs::zero()));
768	
769	    let radius = radius
770	        .zip(corner_max)
771	        .map(|(value, max)| value.relative_to(max * 2.0).min(max));
772	    let corners = corners_control_points(size, &radius, strokes, &stroke_widths);
773	
774	    // insert stroked sides below filled sides
775	    let mut stroke_insert = 0;
776	
777	    // fill shape with inner curve
778	    if let Some(fill) = fill {
779	        let mut curve = Curve::new();
780	        let c = corners.get_ref(Corner::TopLeft);
781	        if c.arc() {
782	            curve.arc_move(c.start(), c.center(), c.end());
783	        } else {
784	            curve.move_(c.center());
785	        }
786	
787	        for corner in [Corner::TopRight, Corner::BottomRight, Corner::BottomLeft] {
788	            let c = corners.get_ref(corner);
789	            if c.arc() {
790	                curve.arc_line(c.start(), c.center(), c.end());
791	            } else {
792	                curve.line(c.center());
793	            }
794	        }
795	        curve.close();
796	        res.push(Shape {
797	            geometry: Geometry::Curve(curve),
798	            fill: Some(fill),
799	            fill_rule: FillRule::default(),
800	            stroke: None,
801	        });
802	        stroke_insert += 1;
803	    }
804	
805	    let current = corners.iter().find(|c| !c.same).map(|c| c.corner);
806	    if let Some(mut current) = current {
807	        // multiple segments
808	        // start at a corner with a change between sides and iterate clockwise all other corners
809	        let mut last = current;
810	        for _ in 0..4 {
811	            current = current.next_cw();
812	            if corners.get_ref(current).same {
813	                continue;
814	            }
815	            // create segment
816	            let start = last;
817	            let end = current;
818	            last = current;
819	            let Some(stroke) = strokes.get_ref(start.side_cw()) else { continue };
820	            let start_cap = stroke.cap;
821	            let end_cap = match strokes.get_ref(end.side_ccw()) {
822	                Some(stroke) => stroke.cap,
823	                None => start_cap,
824	            };
825	            let (shape, ontop) =
826	                segment(start, end, start_cap, end_cap, &corners, stroke);
827	            if ontop {
828	                res.push(shape);
829	            } else {
830	                res.insert(stroke_insert, shape);
831	                stroke_insert += 1;
832	            }
833	        }
834	    } else if let Some(stroke) = &strokes.top {
835	        // single segment
836	        let (shape, _) = segment(
837	            Corner::TopLeft,
838	            Corner::TopLeft,
839	            stroke.cap,
840	            stroke.cap,
841	            &corners,
842	            stroke,
843	        );
844	        res.push(shape);
845	    }
846	    res
847	}
848	
849	fn curve_segment(
850	    start: Corner,
851	    end: Corner,
852	    corners: &Corners<ControlPoints>,
853	    curve: &mut Curve,
854	) {
855	    // create start corner
856	    let c = corners.get_ref(start);
857	    if start == end || !c.arc() {
858	        curve.move_(c.end());
859	    } else {
860	        curve.arc_move(c.mid(), c.center(), c.end());
861	    }
862	
863	    // create corners between start and end
864	    let mut current = start.next_cw();
865	    while current != end {
866	        let c = corners.get_ref(current);
867	        if c.arc() {
868	            curve.arc_line(c.start(), c.center(), c.end());
869	        } else {
870	            curve.line(c.end());
871	        }
872	        current = current.next_cw();
873	    }
874	
875	    // create end corner
876	    let c = corners.get_ref(end);
877	    if !c.arc() {
878	        curve.line(c.start());
879	    } else if start == end {
880	        curve.arc_line(c.start(), c.center(), c.end());
881	    } else {
882	        curve.arc_line(c.start(), c.center(), c.mid());
883	    }
884	}
