886	/// Returns the shape for the segment and whether the shape should be drawn on top.
887	fn segment(
888	    start: Corner,
889	    end: Corner,
890	    start_cap: LineCap,
891	    end_cap: LineCap,
892	    corners: &Corners<ControlPoints>,
893	    stroke: &FixedStroke,
894	) -> (Shape, bool) {
895	    fn fill_corner(corner: &ControlPoints) -> bool {
896	        corner.stroke_before != corner.stroke_after
897	            || corner.radius() < corner.stroke_width_before()
898	    }
899	
900	    fn fill_corners(
901	        start: Corner,
902	        end: Corner,
903	        corners: &Corners<ControlPoints>,
904	    ) -> bool {
905	        if fill_corner(corners.get_ref(start)) {
906	            return true;
907	        }
908	        if fill_corner(corners.get_ref(end)) {
909	            return true;
910	        }
911	        let mut current = start.next_cw();
912	        while current != end {
913	            if fill_corner(corners.get_ref(current)) {
914	                return true;
915	            }
916	            current = current.next_cw();
917	        }
918	        false
919	    }
920	
921	    let solid = stroke.dash.as_ref().map(|dash| dash.array.is_empty()).unwrap_or(true);
922	
923	    let use_fill = solid && fill_corners(start, end, corners);
924	    let shape = if use_fill {
925	        fill_segment(start, end, start_cap, end_cap, corners, stroke)
926	    } else {
927	        stroke_segment(start, end, corners, stroke.clone())
928	    };
929	
930	    (shape, use_fill)
931	}
932	
933	/// Stroke the sides from `start` to `end` clockwise.
934	fn stroke_segment(
935	    start: Corner,
936	    end: Corner,
937	    corners: &Corners<ControlPoints>,
938	    stroke: FixedStroke,
939	) -> Shape {
940	    // Create start corner.
941	    let mut curve = Curve::new();
942	    curve_segment(start, end, corners, &mut curve);
943	
944	    Shape {
945	        geometry: Geometry::Curve(curve),
946	        stroke: Some(stroke),
947	        fill: None,
948	        fill_rule: FillRule::default(),
949	    }
950	}
951	
952	/// Fill the sides from `start` to `end` clockwise.
953	fn fill_segment(
954	    start: Corner,
955	    end: Corner,
956	    start_cap: LineCap,
957	    end_cap: LineCap,
958	    corners: &Corners<ControlPoints>,
959	    stroke: &FixedStroke,
960	) -> Shape {
961	    let mut curve = Curve::new();
962	
963	    // create the start corner
964	    // begin on the inside and finish on the outside
965	    // no corner if start and end are equal
966	    // half corner if different
967	    if start == end {
968	        let c = corners.get_ref(start);
969	        curve.move_(c.end_inner());
970	        curve.line(c.end_outer());
971	    } else {
972	        let c = corners.get_ref(start);
973	
974	        if c.arc_inner() {
975	            curve.arc_move(c.end_inner(), c.center_inner(), c.mid_inner());
976	        } else {
977	            curve.move_(c.end_inner());
978	        }
979	
980	        c.start_cap(&mut curve, start_cap);
981	        if c.arc_outer() {
982	            curve.arc_line(c.mid_outer(), c.center_outer(), c.end_outer());
983	        }
984	    }
985	
986	    // create the clockwise outside curve for the corners between start and end
987	    let mut current = start.next_cw();
988	    while current != end {
989	        let c = corners.get_ref(current);
990	        if c.arc_outer() {
991	            curve.arc_line(c.start_outer(), c.center_outer(), c.end_outer());
992	        } else {
993	            curve.line(c.outer());
994	        }
995	        current = current.next_cw();
996	    }
997	
998	    // create the end corner
999	    // begin on the outside and finish on the inside
1000	    // full corner if start and end are equal
1001	    // half corner if different
1002	    if start == end {
1003	        let c = corners.get_ref(end);
1004	        if c.arc_outer() {
1005	            curve.arc_line(c.start_outer(), c.center_outer(), c.end_outer());
1006	        } else {
1007	            curve.line(c.outer());
1008	            curve.line(c.end_outer());
1009	        }
1010	        if c.arc_inner() {
1011	            curve.arc_line(c.end_inner(), c.center_inner(), c.start_inner());
1012	        } else {
1013	            curve.line(c.center_inner());
1014	        }
1015	    } else {
1016	        let c = corners.get_ref(end);
1017	        if c.arc_outer() {
1018	            curve.arc_line(c.start_outer(), c.center_outer(), c.mid_outer());
1019	        } else {
1020	            curve.line(c.outer());
1021	        }
1022	        c.end_cap(&mut curve, end_cap);
1023	        if c.arc_inner() {
1024	            curve.arc_line(c.mid_inner(), c.center_inner(), c.start_inner());
1025	        }
1026	    }
1027	
1028	    // create the counterclockwise inside curve for the corners between start and end
1029	    let mut current = end.next_ccw();
1030	    while current != start {
1031	        let c = corners.get_ref(current);
1032	        if c.arc_inner() {
1033	            curve.arc_line(c.end_inner(), c.center_inner(), c.start_inner());
1034	        } else {
1035	            curve.line(c.center_inner());
1036	        }
1037	        current = current.next_ccw();
1038	    }
1039	
1040	    curve.close();
1041	
1042	    Shape {
1043	        geometry: Geometry::Curve(curve),
1044	        stroke: None,
1045	        fill: Some(stroke.paint.clone()),
1046	        fill_rule: FillRule::default(),
1047	    }
1048	}
1049	
1050	/// Helper to calculate different control points for the corners.
1051	/// Clockwise orientation from start to end.
1052	/// ```text
1053	/// O-------------------EO  ---   - Z: Zero/Origin ({x: 0, y: 0} for top left corner)
1054	/// |\   ___----'''     |    |    - O: Outer: intersection between the straight outer lines
1055	/// | \ /               |    |    - S_: start
1056	/// |  MO               |    |    - M_: midpoint
1057	/// | /Z\  __-----------E    |    - E_: end
1058	/// |/   \M             |    ro   - r_: radius
1059	/// |    /\             |    |    - middle of the stroke
1060	/// |   /  \            |    |      - arc from S through M to E with center C and radius r
1061	/// |  |    MI--EI-------    |    - outer curve
1062	/// |  |  /  \               |      - arc from SO through MO to EO with center CO and radius ro
1063	/// SO | |    \         CO  ---   - inner curve
1064	/// |  | |     \                    - arc from SI through MI to EI with center CI and radius ri
1065	/// |--S-SI-----CI      C
1066	///      |--ri--|
1067	///    |-------r--------|
1068	/// ```
1069	struct ControlPoints {
1070	    radius: Abs,
1071	    stroke_after: Option<Abs>,
1072	    stroke_before: Option<Abs>,
1073	    corner: Corner,
1074	    size: Size,
1075	    same: bool,
1076	}
1077	
1078	impl ControlPoints {
1079	    /// Move and rotate the point from top-left to the required corner.
1080	    fn rotate(&self, point: Point) -> Point {
1081	        match self.corner {
1082	            Corner::TopLeft => Point {
1083	                x: self.size.x.signum() * point.x,
1084	                y: self.size.y.signum() * point.y,
1085	            },
1086	            Corner::TopRight => Point {
1087	                x: self.size.x - self.size.x.signum() * point.y,
1088	                y: self.size.y.signum() * point.x,
1089	            },
1090	            Corner::BottomRight => Point {
1091	                x: self.size.x - self.size.x.signum() * point.x,
1092	                y: self.size.y - self.size.y.signum() * point.y,
1093	            },
1094	            Corner::BottomLeft => Point {
1095	                x: self.size.x.signum() * point.y,
1096	                y: self.size.y - self.size.y.signum() * point.x,
1097	            },
1098	        }
1099	    }
1100	
1101	    /// Whether to use the [`Self::stroke_after`] if [`Self::stroke_before`] is
1102	    /// missing to compute the control points. If the radius is too small, caps
1103	    /// other than the [`LineCap::Butt`] might be misshaped.
1104	    fn reuse_stroke_after_for_cap(&self) -> Option<Abs> {
1105	        self.stroke_after.filter(|s| 2.0 * *s < self.radius)
1106	    }
1107	
1108	    /// Either fall back to [`Self::reuse_stroke_after_for_cap`] or zero.
1109	    fn stroke_width_before(&self) -> Abs {
1110	        self.stroke_before
1111	            .or(self.reuse_stroke_after_for_cap())
1112	            .unwrap_or(Abs::zero())
1113	    }
1114	
1115	    /// Whether to use the [`Self::stroke_before`] if [`Self::stroke_after`] is
1116	    /// missing to compute the control points. If the radius is too small, caps
1117	    /// other than the [`LineCap::Butt`] might be misshaped.
1118	    fn reuse_stroke_before_for_cap(&self) -> Option<Abs> {
1119	        self.stroke_before.filter(|s| 2.0 * *s < self.radius)
1120	    }
1121	
1122	    /// Either fall back to [`Self::reuse_stroke_before_for_cap`] or zero.
1123	    fn stroke_width_after(&self) -> Abs {
1124	        self.stroke_after
1125	            .or(self.reuse_stroke_before_for_cap())
1126	            .unwrap_or(Abs::zero())
1127	    }
1128	
1129	    /// Outside intersection of the sides.
1130	    pub fn outer(&self) -> Point {
1131	        self.rotate(Point {
1132	            x: -self.stroke_width_before(),
1133	            y: -self.stroke_width_after(),
1134	        })
1135	    }
1136	
1137	    /// Center for the outer arc.
1138	    pub fn center_outer(&self) -> Point {
1139	        let r = self.radius_outer();
1140	        self.rotate(Point {
1141	            x: r - self.stroke_width_before(),
1142	            y: r - self.stroke_width_after(),
1143	        })
1144	    }
1145	
1146	    /// Center for the middle arc.
1147	    pub fn center(&self) -> Point {
1148	        let r = self.radius();
1149	        self.rotate(Point { x: r, y: r })
1150	    }
1151	
1152	    /// Center for the inner arc.
1153	    pub fn center_inner(&self) -> Point {
1154	        let r = self.radius_inner();
1155	
1156	        self.rotate(Point {
1157	            x: self.stroke_width_before() + r,
1158	            y: self.stroke_width_after() + r,
1159	        })
1160	    }
1161	
1162	    /// Radius of the outer arc.
1163	    pub fn radius_outer(&self) -> Abs {
1164	        self.radius
1165	    }
1166	
1167	    /// Radius of the middle arc.
1168	    pub fn radius(&self) -> Abs {
1169	        (self.radius - self.stroke_width_before().min(self.stroke_width_after()))
1170	            .max(Abs::zero())
1171	    }
1172	
1173	    /// Radius of the inner arc.
1174	    pub fn radius_inner(&self) -> Abs {
1175	        (self.radius - 2.0 * self.stroke_width_before().max(self.stroke_width_after()))
1176	            .max(Abs::zero())
1177	    }
1178	
1179	    /// Middle of the corner on the outside of the stroke.
1180	    pub fn mid_outer(&self) -> Point {
1181	        let c_i = self.center_inner();
1182	        let c_o = self.center_outer();
1183	        let o = self.outer();
1184	        let r = self.radius_outer();
1185	
1186	        // https://math.stackexchange.com/a/311956
1187	        // intersection between the line from inner center to outside and the outer arc
1188	        let a = (o.x - c_i.x).scalar().powi(2) + (o.y - c_i.y).scalar().powi(2);
1189	        let b = 2.0 * (o.x - c_i.x).scalar() * (c_i.x - c_o.x).scalar()
1190	            + 2.0 * (o.y - c_i.y).scalar() * (c_i.y - c_o.y).scalar();
1191	        let c = (c_i.x - c_o.x).scalar().powi(2) + (c_i.y - c_o.y).scalar().powi(2)
1192	            - r.scalar().powi(2);
1193	        let t = (-b + (b * b - 4.0 * a * c).max(0.0.into()).sqrt()) / (2.0 * a);
1194	        c_i + t.get() * (o - c_i)
1195	    }
1196	
1197	    /// Middle of the corner in the middle of the stroke.
1198	    pub fn mid(&self) -> Point {
1199	        let center = self.center();
1200	        let outer = self.outer();
1201	        let diff = outer - center;
1202	        center + diff / diff.hypot().to_raw() * self.radius().to_raw()
1203	    }
1204	
1205	    /// Middle of the corner on the inside of the stroke.
1206	    pub fn mid_inner(&self) -> Point {
1207	        let center = self.center_inner();
1208	        let outer = self.outer();
1209	        let diff = outer - center;
1210	        center + diff / diff.hypot().to_raw() * self.radius_inner().to_raw()
1211	    }
1212	
1213	    /// If an outer arc is required.
1214	    pub fn arc_outer(&self) -> bool {
1215	        self.radius_outer() > Abs::zero()
1216	    }
1217	
1218	    pub fn arc(&self) -> bool {
1219	        self.radius() > Abs::zero()
1220	    }
1221	
1222	    /// If an inner arc is required.
1223	    pub fn arc_inner(&self) -> bool {
1224	        self.radius_inner() > Abs::zero()
1225	    }
1226	
1227	    /// Start of the corner on the outside of the stroke.
1228	    pub fn start_outer(&self) -> Point {
1229	        self.rotate(Point {
1230	            x: -self.stroke_width_before(),
1231	            y: self.radius_outer() - self.stroke_width_after(),
1232	        })
1233	    }
1234	
1235	    /// Start of the corner in the center of the stroke.
1236	    pub fn start(&self) -> Point {
1237	        self.rotate(Point::with_y(self.radius()))
1238	    }
1239	
1240	    /// Start of the corner on the inside of the stroke.
1241	    pub fn start_inner(&self) -> Point {
1242	        self.rotate(Point {
1243	            x: self.stroke_width_before(),
1244	            y: self.stroke_width_after() + self.radius_inner(),
1245	        })
1246	    }
1247	
1248	    /// End of the corner on the outside of the stroke.
1249	    pub fn end_outer(&self) -> Point {
1250	        self.rotate(Point {
1251	            x: self.radius_outer() - self.stroke_width_before(),
1252	            y: -self.stroke_width_after(),
1253	        })
1254	    }
1255	
1256	    /// End of the corner in the center of the stroke.
1257	    pub fn end(&self) -> Point {
1258	        self.rotate(Point::with_x(self.radius()))
1259	    }
1260	
1261	    /// End of the corner on the inside of the stroke.
1262	    pub fn end_inner(&self) -> Point {
1263	        self.rotate(Point {
1264	            x: self.stroke_width_before() + self.radius_inner(),
1265	            y: self.stroke_width_after(),
1266	        })
1267	    }
1268	
1269	    /// Draw the cap at the beginning of the segment.
1270	    ///
1271	    /// If this corner has a stroke before it,
1272	    /// a default "butt" cap is used.
1273	    pub fn start_cap(&self, curve: &mut Curve, cap_type: LineCap) {
1274	        // Avoid misshaped caps on small radii.
1275	        let small_radius = self.reuse_stroke_after_for_cap().is_none();
1276	        if cap_type == LineCap::Butt
1277	            || self.stroke_before.is_some()
1278	            || self.radius != Abs::zero() && small_radius
1279	        {
