1281	            curve.line(self.mid_outer());
1282	        } else if cap_type == LineCap::Square {
1283	            let butt_start = self.mid_inner();
1284	            let butt_end = self.mid_outer();
1285	            // Extend by the stroke width.
1286	            let offset_dir = line_normal(butt_start, butt_end);
1287	            let offset = self.stroke_width_after().to_raw() * offset_dir;
1288	            curve.line(butt_start + offset);
1289	            curve.line(butt_end + offset);
