1291	        } else if cap_type == LineCap::Round {
1292	            let arc_start = self.mid_inner();
1293	            let arc_end = self.mid_outer();
1294	            // We push the center by a little bit to ensure the correct
1295	            // half of the circle gets drawn. If it is perfectly centered
1296	            // the `arc` function just degenerates into a line, which we
1297	            // do not want in this case.
1298	            let offset_dir = -line_normal(arc_start, arc_end);
1299	            let arc_center = (arc_start + arc_end) / 2.0 + offset_dir;
1300	            curve.arc(arc_start, arc_center, arc_end);
