1304	    /// Draw the cap at the end of the segment.
1305	    ///
1306	    /// If this corner has a stroke before it,
1307	    /// a default "butt" cap is used.
1308	    pub fn end_cap(&self, curve: &mut Curve, cap_type: LineCap) {
1309	        // Avoid misshaped caps on small radii.
1310	        let small_radius = self.reuse_stroke_before_for_cap().is_none();
1311	        if cap_type == LineCap::Butt
1312	            || self.stroke_after.is_some()
1313	            || self.radius != Abs::zero() && small_radius
1314	        {
1315	            // Just the default cap.
1316	            curve.line(self.mid_inner());
1317	        } else if cap_type == LineCap::Square {
1318	            let butt_start = self.mid_outer();
1319	            let butt_end = self.mid_inner();
1320	            // Extend by the stroke width.
1321	            let offset_dir = line_normal(butt_start, butt_end);
1322	            let offset = self.stroke_width_before().to_raw() * offset_dir;
1323	            curve.line(butt_start + offset);
1324	            curve.line(butt_end + offset);
1325	            curve.line(butt_end);
1326	        } else if cap_type == LineCap::Round {
1327	            let arc_start = self.mid_outer();
1328	            let arc_end = self.mid_inner();
1329	            // We push the center by a little bit to ensure the correct
1330	            // half of the circle gets drawn. If it is perfectly centered
1331	            // the `arc` function just degenerates into a line, which we
1332	            // do not want in this case.
1333	            let arc_center_offset = -line_normal(arc_start, arc_end);
1334	            let arc_center = (arc_start + arc_end) / 2.0 + arc_center_offset;
1335	            curve.arc(arc_start, arc_center, arc_end);
1336	        }
1337	    }
1338	}
1339	
1340	/// Computes the normal vector towards the left of the line.
1341	fn line_normal(start: Point, end: Point) -> Point {
1342	    (end - start).rot90ccw().normalized()
1343	}
1344	
1345	/// Helper to draw arcs with Bézier curves.
1346	trait CurveExt {
1347	    fn arc(&mut self, start: Point, center: Point, end: Point);
1348	    fn arc_move(&mut self, start: Point, center: Point, end: Point);
1349	    fn arc_line(&mut self, start: Point, center: Point, end: Point);
