1369	/// Get the control points for a Bézier curve that approximates a circular arc for
1370	/// a start point, an end point and a center of the circle whose arc connects
1371	/// the two.
1372	fn bezier_arc_control(start: Point, center: Point, end: Point) -> [Point; 2] {
